(window.__quranSurahs=window.__quranSurahs||{})[56]={"nomPhon":"Al-Waaqia","versets":{"1":{"text":"Quand l'événement (le Jugement) arrivera,","arabe":"إِذَا وَقَعَتِ ٱلْوَاقِعَةُ"},"2":{"text":"nul ne traitera sa venue de mensonge.","arabe":"لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ"},"3":{"text":"Il abaissera (les uns), il élèvera (les autres).","arabe":"خَافِضَةٌۭ رَّافِعَةٌ"},"4":{"text":"Quand la terre sera secouée violemment,","arabe":"إِذَا رُجَّتِ ٱلْأَرْضُ رَجًّۭا"},"5":{"text":"et les montagnes seront réduites en miettes,","arabe":"وَبُسَّتِ ٱلْجِبَالُ بَسًّۭا"},"6":{"text":"et qu'elles deviendront poussière éparpillée","arabe":"فَكَانَتْ هَبَآءًۭ مُّنۢبَثًّۭا"},"7":{"text":"alors vous serez trois catégories:","arabe":"وَكُنتُمْ أَزْوَٰجًۭا ثَلَٰثَةًۭ"},"8":{"text":"les gens de la droite - que sont les gens de la droite?","arabe":"فَأَصْحَٰبُ ٱلْمَيْمَنَةِ مَآ أَصْحَٰبُ ٱلْمَيْمَنَةِ"},"9":{"text":"Et les gens de la gauche - que sont les gens de la gauche?","arabe":"وَأَصْحَٰبُ ٱلْمَشْـَٔمَةِ مَآ أَصْحَٰبُ ٱلْمَشْـَٔمَةِ"},"10":{"text":"Les premiers (à suivre les ordres d'Allah sur la terre) ce sont eux qui seront les premiers (dans l'au-delà)","arabe":"وَٱلسَّٰبِقُونَ ٱلسَّٰبِقُونَ"},"11":{"text":"Ce sont ceux-là les plus rapprochés d'Allah","arabe":"أُو۟لَٰٓئِكَ ٱلْمُقَرَّبُونَ"},"12":{"text":"dans les Jardins des délices,","arabe":"فِى جَنَّٰتِ ٱلنَّعِيمِ"},"13":{"text":"une multitude d'élus parmi les premières [générations],","arabe":"ثُلَّةٌۭ مِّنَ ٱلْأَوَّلِينَ"},"14":{"text":"et un petit nombre parmi les dernières [générations],","arabe":"وَقَلِيلٌۭ مِّنَ ٱلْءَاخِرِينَ"},"15":{"text":"sur des lits ornés [d'or et de pierreries],","arabe":"عَلَىٰ سُرُرٍۢ مَّوْضُونَةٍۢ"},"16":{"text":"s'y accoudant et se faisant face.","arabe":"مُّتَّكِـِٔينَ عَلَيْهَا مُتَقَٰبِلِينَ"},"17":{"text":"Parmi eux circuleront des garçons éternellement jeunes,","arabe":"يَطُوفُ عَلَيْهِمْ وِلْدَٰنٌۭ مُّخَلَّدُونَ"},"18":{"text":"avec des coupes, des aiguières et un verre [rempli] d'une liqueur de source","arabe":"بِأَكْوَابٍۢ وَأَبَارِيقَ وَكَأْسٍۢ مِّن مَّعِينٍۢ"},"19":{"text":"qui ne leur provoquera ni maux de tête ni étourdissement;","arabe":"لَّا يُصَدَّعُونَ عَنْهَا وَلَا يُنزِفُونَ"},"20":{"text":"et des fruits de leur choix,","arabe":"وَفَٰكِهَةٍۢ مِّمَّا يَتَخَيَّرُونَ"},"21":{"text":"et toute chair d'oiseau qu'ils désireront.","arabe":"وَلَحْمِ طَيْرٍۢ مِّمَّا يَشْتَهُونَ"},"22":{"text":"Et ils auront des houris aux yeux, grands et beaux,","arabe":"وَحُورٌ عِينٌۭ"},"23":{"text":"pareilles à des perles en coquille","arabe":"كَأَمْثَٰلِ ٱللُّؤْلُؤِ ٱلْمَكْنُونِ"},"24":{"text":"en récompense pour ce qu'ils faisaient.","arabe":"جَزَآءًۢ بِمَا كَانُوا۟ يَعْمَلُونَ"},"25":{"text":"Ils n'y entendront ni futilité ni blasphème;","arabe":"لَا يَسْمَعُونَ فِيهَا لَغْوًۭا وَلَا تَأْثِيمًا"},"26":{"text":"mais seulement les propos: «Salâm! Salâm!»... [Paix! Paix!]","arabe":"إِلَّا قِيلًۭا سَلَٰمًۭا سَلَٰمًۭا"},"27":{"text":"Et les gens de la droite; que sont les gens de la droite?","arabe":"وَأَصْحَٰبُ ٱلْيَمِينِ مَآ أَصْحَٰبُ ٱلْيَمِينِ"},"28":{"text":"[Ils seront parmi] des jujubiers sans épines,","arabe":"فِى سِدْرٍۢ مَّخْضُودٍۢ"},"29":{"text":"et parmi des bananiers aux régimes bien fournis,","arabe":"وَطَلْحٍۢ مَّنضُودٍۢ"},"30":{"text":"dans une ombre étendue","arabe":"وَظِلٍّۢ مَّمْدُودٍۢ"},"31":{"text":"[près] d'une eau coulant continuellement,","arabe":"وَمَآءٍۢ مَّسْكُوبٍۢ"},"32":{"text":"et des fruits abondants","arabe":"وَفَٰكِهَةٍۢ كَثِيرَةٍۢ"},"33":{"text":"ni interrompus ni défendus,","arabe":"لَّا مَقْطُوعَةٍۢ وَلَا مَمْنُوعَةٍۢ"},"34":{"text":"sur des lits surélevés,","arabe":"وَفُرُشٍۢ مَّرْفُوعَةٍ"},"35":{"text":"C'est Nous qui les avons créées à la perfection,","arabe":"إِنَّآ أَنشَأْنَٰهُنَّ إِنشَآءًۭ"},"36":{"text":"et Nous les avons faites vierges,","arabe":"فَجَعَلْنَٰهُنَّ أَبْكَارًا"},"37":{"text":"gracieuses, toutes de même âge,","arabe":"عُرُبًا أَتْرَابًۭا"},"38":{"text":"pour les gens de la droite,","arabe":"لِّأَصْحَٰبِ ٱلْيَمِينِ"},"39":{"text":"une multitude d'élus parmi les premières [générations],","arabe":"ثُلَّةٌۭ مِّنَ ٱلْأَوَّلِينَ"},"40":{"text":"et une multitude d'élus parmi les dernières [générations].","arabe":"وَثُلَّةٌۭ مِّنَ ٱلْءَاخِرِينَ"},"41":{"text":"Et les gens de la gauche; que sont les gens de la gauche?","arabe":"وَأَصْحَٰبُ ٱلشِّمَالِ مَآ أَصْحَٰبُ ٱلشِّمَالِ"},"42":{"text":"ils seront au milieu d'un souffle brûlant et d'une eau bouillante,","arabe":"فِى سَمُومٍۢ وَحَمِيمٍۢ"},"43":{"text":"à l'ombre d'une fumée noire","arabe":"وَظِلٍّۢ مِّن يَحْمُومٍۢ"},"44":{"text":"ni fraîche, ni douce.","arabe":"لَّا بَارِدٍۢ وَلَا كَرِيمٍ"},"45":{"text":"Ils vivaient auparavant dans le luxe.","arabe":"إِنَّهُمْ كَانُوا۟ قَبْلَ ذَٰلِكَ مُتْرَفِينَ"},"46":{"text":"Ils persistaient dans le grand péché [le polythéisme]","arabe":"وَكَانُوا۟ يُصِرُّونَ عَلَى ٱلْحِنثِ ٱلْعَظِيمِ"},"47":{"text":"et disaient: «Quand nous mourrons et serons poussière et ossements, serons-nous ressuscités?","arabe":"وَكَانُوا۟ يَقُولُونَ أَئِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَٰمًا أَءِنَّا لَمَبْعُوثُونَ"},"48":{"text":"ainsi que nos anciens ancêtres?..»","arabe":"أَوَءَابَآؤُنَا ٱلْأَوَّلُونَ"},"49":{"text":"Dis: «En vérité les premiers et les derniers","arabe":"قُلْ إِنَّ ٱلْأَوَّلِينَ وَٱلْءَاخِرِينَ"},"50":{"text":"seront réunis pour le rendez-vous d'un jour connu».","arabe":"لَمَجْمُوعُونَ إِلَىٰ مِيقَٰتِ يَوْمٍۢ مَّعْلُومٍۢ"},"51":{"text":"Et puis, vous, les égarés, qui traitiez (la Résurrection) de mensonge,","arabe":"ثُمَّ إِنَّكُمْ أَيُّهَا ٱلضَّآلُّونَ ٱلْمُكَذِّبُونَ"},"52":{"text":"vous mangerez certainement d'un arbre de Zaqqûm.","arabe":"لَءَاكِلُونَ مِن شَجَرٍۢ مِّن زَقُّومٍۢ"},"53":{"text":"vous vous en remplirez le ventre,","arabe":"فَمَالِـُٔونَ مِنْهَا ٱلْبُطُونَ"},"54":{"text":"puis vous boirez par-dessus cela de l'eau bouillante,","arabe":"فَشَٰرِبُونَ عَلَيْهِ مِنَ ٱلْحَمِيمِ"},"55":{"text":"vous en boirez comme boivent les chameaux assoiffés.","arabe":"فَشَٰرِبُونَ شُرْبَ ٱلْهِيمِ"},"56":{"text":"Voilà le repas d'accueil qui leur sera servi, au jour de la Rétribution.","arabe":"هَٰذَا نُزُلُهُمْ يَوْمَ ٱلدِّينِ"},"57":{"text":"C'est Nous qui vous avons créés. Pourquoi ne croiriez-vous donc pas [à la résurrection]?","arabe":"نَحْنُ خَلَقْنَٰكُمْ فَلَوْلَا تُصَدِّقُونَ"},"58":{"text":"Voyez-vous donc ce que vous éjaculez:","arabe":"أَفَرَءَيْتُم مَّا تُمْنُونَ"},"59":{"text":"est-ce vous qui le créez ou [en] sommes Nous le Créateur?","arabe":"ءَأَنتُمْ تَخْلُقُونَهُۥٓ أَمْ نَحْنُ ٱلْخَٰلِقُونَ"},"60":{"text":"Nous avons prédéterminé la mort parmi vous. Nous ne serons point empêchés","arabe":"نَحْنُ قَدَّرْنَا بَيْنَكُمُ ٱلْمَوْتَ وَمَا نَحْنُ بِمَسْبُوقِينَ"},"61":{"text":"de vous remplacer par vos semblables, et vous faire renaître dans [un état] que vous ne savez pas.","arabe":"عَلَىٰٓ أَن نُّبَدِّلَ أَمْثَٰلَكُمْ وَنُنشِئَكُمْ فِى مَا لَا تَعْلَمُونَ"},"62":{"text":"Vous avez connu la première création. Ne vous rappelez-vous donc pas?","arabe":"وَلَقَدْ عَلِمْتُمُ ٱلنَّشْأَةَ ٱلْأُولَىٰ فَلَوْلَا تَذَكَّرُونَ"},"63":{"text":"Voyez-vous donc ce que vous labourez?","arabe":"أَفَرَءَيْتُم مَّا تَحْرُثُونَ"},"64":{"text":"Est-ce vous qui le cultivez? ou [en] sommes Nous le cultivateur?","arabe":"ءَأَنتُمْ تَزْرَعُونَهُۥٓ أَمْ نَحْنُ ٱلزَّٰرِعُونَ"},"65":{"text":"Si Nous voulions, Nous le réduirions en débris. Et vous ne cesseriez pas de vous étonner et [de crier]:","arabe":"لَوْ نَشَآءُ لَجَعَلْنَٰهُ حُطَٰمًۭا فَظَلْتُمْ تَفَكَّهُونَ"},"66":{"text":"«Nous voilà endettés!","arabe":"إِنَّا لَمُغْرَمُونَ"},"67":{"text":"ou plutôt, exposés aux privations».","arabe":"بَلْ نَحْنُ مَحْرُومُونَ"},"68":{"text":"Voyez-vous donc l'eau que vous buvez?","arabe":"أَفَرَءَيْتُمُ ٱلْمَآءَ ٱلَّذِى تَشْرَبُونَ"},"69":{"text":"Est-ce vous qui l'avez fait descendre du nuage? ou [en] sommes Nous le descendeur?","arabe":"ءَأَنتُمْ أَنزَلْتُمُوهُ مِنَ ٱلْمُزْنِ أَمْ نَحْنُ ٱلْمُنزِلُونَ"},"70":{"text":"Si Nous voulions, Nous la rendrions salée. Pourquoi n'êtes-vous donc pas reconnaissants?","arabe":"لَوْ نَشَآءُ جَعَلْنَٰهُ أُجَاجًۭا فَلَوْلَا تَشْكُرُونَ"},"71":{"text":"Voyez-vous donc le feu que vous obtenez par frottement?","arabe":"أَفَرَءَيْتُمُ ٱلنَّارَ ٱلَّتِى تُورُونَ"},"72":{"text":"Est-ce vous qui avez créé son arbre ou [en] sommes Nous le Créateur?","arabe":"ءَأَنتُمْ أَنشَأْتُمْ شَجَرَتَهَآ أَمْ نَحْنُ ٱلْمُنشِـُٔونَ"},"73":{"text":"Nous en avons fait un rappel (de l'Enfer), et un élément utile pour ceux qui en ont besoin.","arabe":"نَحْنُ جَعَلْنَٰهَا تَذْكِرَةًۭ وَمَتَٰعًۭا لِّلْمُقْوِينَ"},"74":{"text":"Glorifie donc le nom de ton Seigneur, le Très Grand!","arabe":"فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ"},"75":{"text":"Non!.. Je jure par les positions des étoiles (dans le firmament).","arabe":"۞ فَلَآ أُقْسِمُ بِمَوَٰقِعِ ٱلنُّجُومِ"},"76":{"text":"Et c'est vraiment un serment solennel, si vous saviez.","arabe":"وَإِنَّهُۥ لَقَسَمٌۭ لَّوْ تَعْلَمُونَ عَظِيمٌ"},"77":{"text":"Et c'est certainement un Coran noble,","arabe":"إِنَّهُۥ لَقُرْءَانٌۭ كَرِيمٌۭ"},"78":{"text":"dans un Livre bien gardé","arabe":"فِى كِتَٰبٍۢ مَّكْنُونٍۢ"},"79":{"text":"que seuls les purifiés touchent;","arabe":"لَّا يَمَسُّهُۥٓ إِلَّا ٱلْمُطَهَّرُونَ"},"80":{"text":"C'est une révélation de la part du Seigneur de l'Univers.","arabe":"تَنزِيلٌۭ مِّن رَّبِّ ٱلْعَٰلَمِينَ"},"81":{"text":"Est-ce ce discours-là que vous traitez de mensonge?","arabe":"أَفَبِهَٰذَا ٱلْحَدِيثِ أَنتُم مُّدْهِنُونَ"},"82":{"text":"Et est-ce pour vous [une façon d'être reconnaissant] à votre subsistance que de traiter (le Coran) de mensonge?","arabe":"وَتَجْعَلُونَ رِزْقَكُمْ أَنَّكُمْ تُكَذِّبُونَ"},"83":{"text":"Lorsque le souffle de la vie remonte à la gorge (d'un moribond),","arabe":"فَلَوْلَآ إِذَا بَلَغَتِ ٱلْحُلْقُومَ"},"84":{"text":"et qu'à ce moment là vous regardez,","arabe":"وَأَنتُمْ حِينَئِذٍۢ تَنظُرُونَ"},"85":{"text":"et que Nous sommes plus proche de lui que vous [qui l'entourez] mais vous ne [le] voyez point.","arabe":"وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنكُمْ وَلَٰكِن لَّا تُبْصِرُونَ"},"86":{"text":"Pourquoi donc, si vous croyez que vous n'avez pas de compte à rendre,","arabe":"فَلَوْلَآ إِن كُنتُمْ غَيْرَ مَدِينِينَ"},"87":{"text":"ne la faites-vous pas revenir [cette âme], si vous êtes véridiques?","arabe":"تَرْجِعُونَهَآ إِن كُنتُمْ صَٰدِقِينَ"},"88":{"text":"Si celui-ci est du nombre des rapprochés (d'Allah),","arabe":"فَأَمَّآ إِن كَانَ مِنَ ٱلْمُقَرَّبِينَ"},"89":{"text":"alors (il aura) du repos, de la grâce et un Jardin de délices.","arabe":"فَرَوْحٌۭ وَرَيْحَانٌۭ وَجَنَّتُ نَعِيمٍۢ"},"90":{"text":"Et s'il est du nombre des gens de la droite,","arabe":"وَأَمَّآ إِن كَانَ مِنْ أَصْحَٰبِ ٱلْيَمِينِ"},"91":{"text":"il sera [accueilli par ces mots]: «Paix à toi» de la part des gens de la droite.","arabe":"فَسَلَٰمٌۭ لَّكَ مِنْ أَصْحَٰبِ ٱلْيَمِينِ"},"92":{"text":"Et s'il est de ceux qui avaient traité de mensonge (la résurrection) et s'étaient égarés,","arabe":"وَأَمَّآ إِن كَانَ مِنَ ٱلْمُكَذِّبِينَ ٱلضَّآلِّينَ"},"93":{"text":"alors, il sera installé dans une eau bouillante,","arabe":"فَنُزُلٌۭ مِّنْ حَمِيمٍۢ"},"94":{"text":"et il brûlera dans la Fournaise.","arabe":"وَتَصْلِيَةُ جَحِيمٍ"},"95":{"text":"C'est cela la pleine certitude.","arabe":"إِنَّ هَٰذَا لَهُوَ حَقُّ ٱلْيَقِينِ"},"96":{"text":"Glorifie donc le nom de ton Seigneur, le Très Grand!","arabe":"فَسَبِّحْ بِٱسْمِ رَبِّكَ ٱلْعَظِيمِ"}}};